typedef struct WBAnchor {
    float x;
    float y;
} WBAnchor;

typedef enum WBActionMode {
    WB_ACTION_MOVE = 0,
    WB_ACTION_PICK,
    WB_ACTION_DROP,
    WB_ACTION_DIG,
    WB_ACTION_FILL,
    WB_ACTION_UPROOT,
    WB_ACTION_PLANT,
    WB_ACTION_PUSH
} WBActionMode;

typedef enum WBScreenMode {
    WB_SCREEN_TITLE = 0,
    WB_SCREEN_WORLD_SELECT,
    WB_SCREEN_GAME
} WBScreenMode;

typedef struct WBMoveState {
    bool active;
    bool blockedWaiting;
    bool resumeGoalAfterStop;
    bool pendingActionValid;
    int pendingActionX;
    int pendingActionY;
    bool queuedMoveValid;
    int queuedMoveX;
    int queuedMoveY;
    WBUnitType unitType;
    int unitEnergy;
    int unitEnergyDeci;
    WBResourcePile unitCargo;
    int unitCargoEnergyValue;  /* charge level (0-100) of any carried energy brick */
    WBDirection finalDirection;
    int goalX;
    int goalY;
    int pathLen;
    int pathIndex;
    WBDirection direction;
    int pathX[WB_MAX_MAP_W * WB_MAX_MAP_H];
    int pathY[WB_MAX_MAP_W * WB_MAX_MAP_H];
    float progress;
    u64 stepStartMs;
    u64 blockedRetryMs;
    u64 swampDamageTickMs;
    int blockedTryNum;
} WBMoveState;

typedef struct WBMonsterState {
    bool active;
    int row;
    int col;
    WBMonsterType type;
    WBDirection dir;
    int hp;            /* 1000 = full health */
    int wanderTimer;   /* per-monster speed scale percentage (80..120) */
    bool onWater;      /* gator: use water sprite set */
    bool dying;
    u64 breakResolveMs;
    bool hasTarget;
    int targetX;
    int targetY;
    u64 nextAttackMs;
    u64 lastAttackMs;
    u64 swampDamageTickMs;
    /* smooth movement */
    bool isMoving;
    int destRow;
    int destCol;
    u64 moveStartMs;
    u64 moveDurationMs;
    float moveProgress; /* 0..1 interpolation progress */
    /* wander timing */
    u64 nextWanderMs;   /* time when monster next picks a new destination */
    bool resting;       /* true = waiting before next step */
    bool targetIsBuilding; /* true = current target is a building, not a unit */
} WBMonsterState;

#define WB_MAX_MONSTERS 32

typedef struct WBAudioClip {
    bool loaded;
    void* data;
    u32 size;
    u32 sampleRate;
    int channels;
    float volume;   /* 0.0 = default (1.0); otherwise applied as mix scale */
    ndspWaveBuf waveBuf;
} WBAudioClip;

typedef struct WBSelectedUnitView {
    bool valid;
    WBUnitType unitType;
    WBTerrainType terrain;
    int energy;
    int energyDeci;
    WBResourcePile cargo;
    WBDirection direction;
} WBSelectedUnitView;

typedef enum WBWorldEffectKind {
    WB_WORLD_EFFECT_DAMAGE_SMALL = 0,
    WB_WORLD_EFFECT_TAKE_APART_CLOUD,
    WB_WORLD_EFFECT_BUILD_CLOUD
} WBWorldEffectKind;

typedef struct WBWorldEffect {
    bool active;
    WBWorldEffectKind kind;
    int tileX;
    int tileY;
    u64 startMs;
    int particleKinds[5];
} WBWorldEffect;

typedef struct WBPendingUnitBreak {
    bool active;
    int tileX;
    int tileY;
    u64 resolveMs;
} WBPendingUnitBreak;

typedef struct WBMiniWalker {
    bool active;
    int world;
    int mission;
    bool bonus;
    bool lake;
    int spriteAssetId;
    float homeX;
    float homeY;
    float x;
    float y;
    float dirX;
    float dirY;
    bool stopped;
    u64 nextDecisionMs;
} WBMiniWalker;

typedef struct WBPlanSwoop {
    bool active;
    int assetId;
    float fromX;
    float fromY;
    float toX;
    float toY;
    u64 startMs;
    u64 durationMs;
} WBPlanSwoop;

